// Des: Commands sync and purge, cloud client setup, alert helper
// Flo: pick the first configured object store + SQL vendor with a key file > sync local queue > purge at 90% > alert at 80% or when an upgrade is needed
// I/O: Ctx (config, keys) > stdout line or JSON, exit code; dry-run never touches the network
// ===================================================================
const std = @import("std"); const cx = @import("ct-ctrl-ctxz.zig"); const stor = @import("sy-clou-stor.zig"); const sqlz = @import("sy-clou-sqlz.zig"); const sync = @import("sy-clou-sync.zig"); const purg = @import("ru-purg-clou.zig"); const outb = @import("sy-clou-outb.zig"); const aler = @import("ob-aler-send.zig"); const live = @import("nt-vend-live.zig"); const pipe = @import("ru-page-fetc.zig"); const cfgz = @import("cf-conf-load.zig"); const b2zz = @import("sy-clou-b2zz.zig"); const r2zz = @import("sy-clou-r2zz.zig"); const tigr = @import("sy-clou-tigr.zig");
const CF = .{ .keyz = 4096, .gibi = 1 << 30, .warn = 80 };
const Info = struct { mode: []const u8, pend_files: i64, pend_recs: i64, store: []const u8, sqlv: []const u8, note: []const u8 };
fn keyText(ctx: *const cx.Ctx, keyd: []const u8, name: []const u8) ?[]const u8 { const path = std.fs.path.join(ctx.allo, &.{ keyd, name }) catch return null; const raws = std.Io.Dir.cwd().readFileAlloc(ctx.iozz, path, ctx.allo, .limited(CF.keyz)) catch return null; const txt = std.mem.trim(u8, raws, " \t\r\n"); return if (txt.len == 0) null else txt; }
fn endpOf(conf: cfgz.Conf, name: []const u8) cfgz.Endp { if (std.mem.eql(u8, name, "b2zz")) return conf.clou_endp.b2zz; if (std.mem.eql(u8, name, "r2zz")) return conf.clou_endp.r2zz; if (std.mem.eql(u8, name, "tigr")) return conf.clou_endp.tigr; if (std.mem.eql(u8, name, "turs")) return conf.clou_endp.turs; if (std.mem.eql(u8, name, "neon")) return conf.clou_endp.neon; return conf.clou_endp.tidb; }
fn capOf(conf: cfgz.Conf, name: []const u8) u64 { const gib: u64 = if (std.mem.eql(u8, name, "b2zz")) conf.clou_capz_gbyt.b2zz else if (std.mem.eql(u8, name, "r2zz")) conf.clou_capz_gbyt.r2zz else conf.clou_capz_gbyt.tigr; return gib * CF.gibi; }
const Pick = struct { s3: stor.S3, net: sqlz.Net, sname: []const u8, qname: []const u8 };
fn pickMake(ctx: *const cx.Ctx, send: @import("nt-vend-base.zig").Send, keyd: []const u8, sidx: usize, qidx: usize) ?Pick { var sfound: usize = 0; var spick: ?stor.S3 = null; var sname: []const u8 = ""; for (ctx.conf.clou_stor_orde) |name| { const ep = endpOf(ctx.conf, name); if (ep.bukt.len == 0) continue; const kt = keyText(ctx, keyd, std.fmt.allocPrint(ctx.allo, "{s}.key", .{name}) catch continue) orelse continue; const pair = stor.keyPair(kt) catch continue; const cred = (if (std.mem.eql(u8, name, "b2zz")) b2zz.credMake(ctx.allo, ep, pair) else if (std.mem.eql(u8, name, "r2zz")) r2zz.credMake(ctx.allo, ep, pair) else tigr.credMake(ctx.allo, ep, pair)) catch continue; if (sfound == sidx) { spick = .{ .cred = cred, .bukt = ep.bukt, .send = send, .gpaz = ctx.init.gpa }; sname = name; break; } sfound += 1; }
var qfound: usize = 0; var qpick: ?sqlz.Net = null; var qname: []const u8 = ""; for (ctx.conf.clou_sqlz_orde) |name| { const ep = endpOf(ctx.conf, name); if (ep.hostz.len == 0) continue; const kt = keyText(ctx, keyd, std.fmt.allocPrint(ctx.allo, "{s}.key", .{name}) catch continue) orelse continue; const kind: sqlz.Kind = if (std.mem.eql(u8, name, "turs")) .turs else if (std.mem.eql(u8, name, "neon")) .neon else .tidb; if (qfound == qidx) { qpick = .{ .kind = kind, .ep = ep, .key = kt, .send = send, .gpaz = ctx.init.gpa }; qname = name; break; } qfound += 1; } if (spick == null or qpick == null) return null; return .{ .s3 = spick.?, .net = qpick.?, .sname = sname, .qname = qname }; }
pub fn alertTry(ctx: *const cx.Ctx, subject: []const u8, text: []const u8) void { const keyd = @import("ut-path-expa.zig").pathExpa(ctx.allo, ctx.home, ctx.conf.vend_keyz_dirz) catch return; var lv: live.Live = .{ .time_mill = 15000 }; const al = aler.alerLoad(ctx.allo, ctx.iozz, keyd, ctx.conf, lv.send(), ctx.init.gpa); _ = aler.alerSend(&al, ctx.allo, ctx.iozz, subject, text) catch {}; }
pub fn runSync(ctx: *const cx.Ctx) !u8 { if (!cx.dbHave(ctx)) { try cx.outz(ctx, "nothing to sync yet"); return 0; } var dbzz = try cx.dbOpen(ctx); defer dbzz.close(); const keyd = @import("ut-path-expa.zig").pathExpa(ctx.allo, ctx.home, ctx.conf.vend_keyz_dirz) catch return error.BadConfig; var lv: live.Live = .{ .time_mill = ctx.conf.fetc_time_seco * 1000 }; const snd = lv.send(); const first = pickMake(ctx, snd, keyd, 0, 0);
if (!ctx.args.live) { const info: Info = .{ .mode = "dry-run", .pend_files = try outb.outbCont(&dbzz, 0), .pend_recs = 0, .store = if (first) |pk| pk.sname else "none", .sqlv = if (first) |pk| pk.qname else "none", .note = "pending counts include files and records; add --live to upload" }; try cx.outz(ctx, try cx.jsonOr(ctx, info, try std.fmt.allocPrint(ctx.allo, "dry-run | {d} queued | store {s} | sql {s} | add --live to upload", .{ info.pend_files, info.store, info.sqlv }))); return 0; }
if (first == null) return error.NotConfigured; var tries: usize = 0; var lasterr: anyerror = error.Fail; while (tries < 3) : (tries += 1) { var pk = pickMake(ctx, snd, keyd, tries, tries) orelse break; var syn: sync.Sync = .{ .iozz = ctx.iozz, .dbzz = &dbzz, .dirz = ctx.dirz, .conf = ctx.conf, .store = pk.s3.store(), .sql = pk.net.sql() }; const now = pipe.nowMs(ctx.iozz); const res = sync.syncRun(&syn, ctx.allo, now) catch |err| { lasterr = err; continue; }; const prs = purg.purgRun(&syn, ctx.allo, now, capOf(ctx.conf, pk.sname)) catch |err| blk: { lasterr = err; break :blk purg.Pres{}; }; if (prs.act == .upgr) alertTry(ctx, "scra cloud full", "cloud is at 90% and clou_poli_mode is upgr: upgrade the plan or switch to purg"); if (prs.cap > 0 and prs.usage * 100 >= prs.cap * CF.warn and prs.act == .none) alertTry(ctx, "scra cloud 80%", "cloud storage passed 80% of the free cap"); const plain = try std.fmt.allocPrint(ctx.allo, "sync | {d} records | {d} files in {s} | purged {d} packs | store {s} sql {s}", .{ res.recs, res.files, res.pack, prs.packs, pk.sname, pk.qname }); try cx.outz(ctx, try cx.jsonOr(ctx, .{ .recs = res.recs, .files = res.files, .pack = res.pack, .purged = prs.packs, .store = pk.sname, .sqlv = pk.qname }, plain)); return 0; } return lasterr; }
